-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.median_answer_ms()
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case
           when count(*) >= 20 then (percentile_cont(0.5) within group (order by recent.duration_ms))::integer
         end
    from (
      select l.duration_ms
        from public.review_log l
       where l.user_id = auth.uid() and l.rating is not null and l.duration_ms is not null
       order by l.reviewed_at desc, l.id desc
       limit 500
    ) recent;
$function$;

grant execute on function public.median_answer_ms() to authenticated;
grant execute on function public.median_answer_ms() to service_role;
